import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const cutoff = new Date(Date.now() - ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000).toISOString();
  const retired = getDb()
    .select({ orgId: retiredOrganizationSlugs.orgId })
    .from(retiredOrganizationSlugs)
    .where(and(eq(retiredOrganizationSlugs.slug, slug), gt(retiredOrganizationSlugs.retiredAt, cutoff)))
    .get();
  if (!retired) return null;
  const org = await findOrgById(retired.orgId as OrgId);
  return org?.archivedAt === null ? org : null;
}

