export async function renameOrgSlug(orgId: OrgId, slug: string): Promise<Organization> {
  const now = new Date();
  const stamp = toIsoTimestamp(now);
  const cutoff = new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000).toISOString();

  const row = getDb().transaction((tx) => {
    const current = tx.select().from(organizations).where(eq(organizations.id, orgId)).get();
    if (!current) throw new Error(`Organization ${orgId} not found`);
    if (current.slug === slug) return current;

    const currentSlugConflict = tx
      .select({ id: organizations.id })
      .from(organizations)
      .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
      .get();
    const retiredConflict = tx
      .select({ slug: retiredOrganizationSlugs.slug })
      .from(retiredOrganizationSlugs)
      .where(and(
        eq(retiredOrganizationSlugs.slug, slug),
        ne(retiredOrganizationSlugs.orgId, orgId),
        gt(retiredOrganizationSlugs.retiredAt, cutoff),
      ))
      .get();
    if (currentSlugConflict || retiredConflict) {
      throw new InvalidSlugError(slug, "is unavailable");
    }

    // A workspace can reclaim a slug it retired itself, and expired holds
    // are removed before the unique slug is inserted again.
    tx.delete(retiredOrganizationSlugs).where(eq(retiredOrganizationSlugs.slug, slug)).run();
    tx.delete(retiredOrganizationSlugs).where(eq(retiredOrganizationSlugs.slug, current.slug)).run();
    tx.insert(retiredOrganizationSlugs).values({
      slug: current.slug,
      orgId,
      retiredAt: stamp,
    }).run();

    return tx.update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
  });
  return toOrganization(row);
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.slug === undefined ? {} : { slug: patch.slug }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  const cutoff = new Date(Date.now() - ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000).toISOString();
  const retiredRows = getDb()
    .select({ slug: retiredOrganizationSlugs.slug })
    .from(retiredOrganizationSlugs)
    .where(and(like(retiredOrganizationSlugs.slug, `${prefix}%`), gt(retiredOrganizationSlugs.retiredAt, cutoff)))
    .all();
  return [...rows.map((row) => row.slug), ...retiredRows.map((row) => row.slug)];
}
